int get_data_block_for_inode(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret = 0;
    struct address_space *mapping = NULL;
    struct page *page = NULL;

    if (!inode || !bh || !next_pgofs) {
        return -EINVAL;
    }

    mapping = inode->i_mapping;
    if (!mapping) {
        return -EINVAL;
    }

    page = read_mapping_page(mapping, iblock, NULL);
    if (IS_ERR(page)) {
        ret = PTR_ERR(page);
        goto out;
    }

    if (!page) {
        ret = -ENOMEM;
        goto out;
    }

    bh->b_page = page;
    bh->b_blocknr = iblock;
    bh->b_size = PAGE_SIZE;

    if (create) {
        ret = block_write_begin(bh, 0, bh->b_size, &page);
        if (ret < 0) {
            goto out;
        }
    }

    *next_pgofs = iblock + 1;

out:
    return ret;
}
